# C3 batch c3ek (round 30, 2026-10-12) of golf_clean.exe: TextView chain, LabelButton and the combo / rich-text chain.
# Reimplementations in shim/src/re/c3ek.cpp; fixtures in re/frida/js/fixtures.d/c3ek.js (generated by
# log/c3/alt/c3ek_gen_fixture.py from log/c3/alt/c3ek_fx/*.js); Purposes and per-jcc branch tables in log/c3/c3ek_purpose.md.
#
# Keys run on objects the game's own constructors built inside the heap stand-in arena ($heap) while the first thread is
# frozen (re/frida/js/uitree.js): UI_STATE compares that arena, the free log, the import log, the recording display's log
# and every window-tree global uitree.js points into the tree.

EXE = "golf_clean.exe"

# re/frida/js/uitree.js: GLOBALS (4 bytes each), the z-list array, the recorder size
UI_GLOBALS = [0x0083AB94, 0x0083AB90, 0x0083AAE0, 0x0083AAEC, 0x0083AAA0, 0x0083AABC, 0x0083AAC0, 0x0083AAC4, 0x0083AA98,
              0x0083AAF0, 0x0083AB30, 0x0083AB34, 0x0083AB40, 0x0083AB44, 0x0083AB54, 0x0083AC18, 0x00839650, 0x0083AB2C,
              0x0083AA9C, 0x0083A2C8, 0x0083A2CC, 0x0083A2D0, 0x0083A2D4, 0x0083AD50, 0x0083AD4C]
REC_SIZE = 0x1000


def UI_STATE(arena):
    return ([("$heap", 0, 0x10 + arena), ("$freelog", 0, 0x404), ("$implog", 0, 0x400), ("$rec", 0, REC_SIZE)]
            + [(g, 0, 4) for g in UI_GLOBALS] + [(0x0083A2D8, 0, 0x200)])


def _h(addr, fixture, vectors, arena, ret="uint32", args=("pointer",), abi="thiscall", extra=()):
    return dict(module=EXE, addr=addr, abi=abi, ret=ret, args=list(args), fixture=fixture,
                state=UI_STATE(arena) + list(extra), vectors=vectors)


HOOKS = {}

