    _fx = f"c3ek_lb_{_v}"
    HOOKS[f"resetMsgObject_{_v}"] = _h(0x004A14C0, _fx, [(o,) for o in _O6] + [(f"$s{i}_x",) for i in range(4)]
                                       + [(f"$s{i}_y",) for i in range(4)], _LA)
    HOOKS[f"LabelButton::dtor_{_v}"] = _h(0x00491410, _fx, [(o,) for o in _O6], _LA)
    HOOKS[f"LabelButton::scalarDtor_{_v}"] = _h(0x00491470, _fx, [(o, f) for o, f in zip(_O6, _FLAGS)], _LA,
                                                ret="pointer", args=("pointer", "int"))
